module polynomial_evaluator (
    input [7:0] a0,
    input [7:0] a1,
    input [7:0] a2,
    input [7:0] a3,
    input [7:0] a4,
    input [3:0] x,
    output [15:0] result
);
    wire [15:0] x_squared;
    wire [15:0] x_cubed;
    wire [15:0] x_quad;

