            a = 8'd0; b = 8'd0; c = 8'd255; x = 8'd123;
            #1;

            check_outputs(16'd255);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Test Case %0d: a is zero (linear function)", test_num);
