            reset_dut();

            enable = 1;
            speed_input = 2'b10;
            @(posedge clk);
            #1;

            enable = 0;
            @(posedge clk);
            #1;
            #1;

            check_outputs(2'b00);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Verification of Reset State", test_num);
            reset_dut();

            #1;


            check_outputs(2'b00);
        end
        endtask

    task testcase008;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Change Speed Input while Disabled", test_num);
            reset_dut();
            enable = 0;
            speed_input = 2'b01;
            @(posedge clk);
            #1;
            speed_input = 2'b10;
            @(posedge clk);
            #1;
            #1;

            check_outputs(2'b00);
        end
        endtask

    // Test stimulus
